      SUBROUTINE GROPECC     ADVANCE PARTIAL DERIVATIVE MATRICES FOR MISALIGNMENTS C     AND FLOOR COORDINATESCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'NELMS.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'OIV.CIN'CC     LOCAL VARIABLESC      INTEGER         VARST      REAL            OS(3,3), XS(3)      EXTERNAL        IDATACC-------------------------------------------------------------------------CC     INDIVIDUAL COORDINATE TRANSFORM  *TIMES*C     DERIVATIVE OF ACCUMULATED COORDINATE TRANSFORMC      IF (.NOT. OMTX) GO TO 200      IF (NV1 .LT. 1) GO TO 200      DO 150 N = 1, NV1      IF (.NOT. OVP(N)) GO TO 150      DO 130 J = 1, 3      S = 0.0      DO 120 K = 1, 3      S1 = 0.0      DO 110 M = 1, 3      S1 = S1 + O(1,J,M)*OV(M,K,N)  110 CONTINUE      OS(J,K) = S1      S = S + OV(K,J,N)*X0(1,K)  120 CONTINUE      X0V(J,N) = X0V(J,N) + S  130 CONTINUE      DO 140 J = 1, 3      DO 140 J1 = 1, 3      OV(J,J1,N) = OS(J,J1)  140 CONTINUE  150 CONTINUECC     DERIVATIVE OF INDIVIDUAL COORDINATE TRANSFORM TIMESC     ACCUMULATED COORDINATE TRANSFORMC  200 NVTYPE = NV(TYPE)      IF (NVTYPE .EQ. 0) GO TO 300      DO 280 JV = 1, NVTYPE      NV2 = VARST(JV)      DPARM = 1.0      IF (NV2 .EQ. 0) GO TO 280      IF (NV2 .LT. 0) DPARM = - 1.0      NVP = 1      IF (NV2 .EQ. 99) THEN        NVP = NPVAR        IF (JV .LE. NELMS(TYPE)) THEN          IADR = I + IPTOJ(JV)  201     IF (TIE(IADR) .EQ. 100) THEN            IADR = IDATA(IADR)            GO TO 201          ENDIF        ELSE IF (TYPE .EQ. 2) THEN          IADR = IBVARY        ELSE          IADR = 0        ENDIF      ENDIF      DO 275 JP = 1, NVP      IF (TYPE .EQ. 13) THEN        NV2 = JV        IF (.NOT. CVP(NV2)) GO TO 280        GO TO 205      ENDIFC      IF (NVP .EQ. NPVAR) THEN        NV2 = JP        DPARM = DATA(IADR + JP)        IF (DPARM .EQ. 0.0) GO TO 275      ENDIFC  205 NV1 = MAX0(NV1,IABS(NV2))      CALL SQUIRM      IF (FLUSHL) GO TO 500      IF (NV2 .LT. 0) THEN        NV2 = IABS(NV2)        DO 208 J = 1, 3        XIV(J) = - XIV(J)        DO 208 K = 1, 3        OIV(J,K) = - OIV(J,K)  208   CONTINUE      ENDIFC      IF (.NOT. OMTX) GO TO 220      DO 213 J = 1, 3      S = 0.0      DO 212 K = 1, 3      S1 = 0.0      DO 211 M = 1, 3      S1 = S1 + OIV(J,M)*O(4,M,K)  211 CONTINUE      OS(J,K) = S1      S = S + O(4,K,J)*XIV(K)  212 CONTINUE      XS(J) = S  213 CONTINUE      GO TO 240C  220 DO 225 J = 1, 3  225 XS(J) = XIV(J)      DO 228 J = 1, 3      DO 228 K = 1, 3  228 OS(J,K) = OIV(J,K)      GO TO 260C  240 IF (OVP(NV2)) GO TO 250      DO 245 J = 1, 3      X0V(J,NV2) = XS(J)      DO 245 K = 1, 3      OV(J,K,NV2) = OS(J,K)  245 CONTINUE      GO TO 270C  250 DO 255 J = 1, 3      X0V(J,NV2) = X0V(J,NV2) + XS(J)      DO 255 K = 1, 3      OV(J,K,NV2) = OV(J,K,NV2) + OS(J,K)  255 CONTINUE      GO TO 270C  260 DO 265 J = 1, 3  265 X0V(J,NV2) = XS(J)      DO 268 J = 1, 3      DO 268 K = 1, 3  268 OV(J,K,NV2) = OS(J,K)C  270 OVP(NV2) = .TRUE.  275 CONTINUE  280 CONTINUECC     ACCUMULATED FLOOR COORDINATESC  300 CALL ADVANC(4)C  500 CONTINUE      RETURN      END